effect.shader:
float rand(vec2 co){ return fract(sin(dot(co.xy ,vec2(12.9898,78.233))) * 43758.5453); }
void main() {
vec2 uv = acScreenNorm;
vec4 base = texture2DCv(inputImg.texture, uv);
float noise = (rand(uv * acTime) - 0.5) * grain;
base.rgb += noise;
base.rgb = (base.rgb - 0.5) * contrast + 0.5;
gl_FragColor = clamp(base, 0.0, 1.0);
}
